<?php
declare(strict_types=1);
require_once __DIR__."/db.php";require_once __DIR__."/funktionen.php";require_once __DIR__."/auth_service.php";
try{berechtigung_pruefen(["administrator"]);}catch(EingabeException $e){http_response_code(403);die(h($e->getMessage()));}
$benutzer=$pdo->query("SELECT id,benutzername,email,rolle,aktiv,kontostatus,erstellt_am FROM benutzer ORDER BY erstellt_am,id")->fetchAll();
$selbstregistrierung=(int)$pdo->query("SELECT selbstregistrierung_aktiv FROM anwendungseinstellungen WHERE id=1")->fetchColumn()===1;
$smtp=smtp_konfiguration();$flash=flash_holen();
$statusNamen=["aktiv"=>"Aktiv","wartend"=>"Wartet auf Freigabe","abgelehnt"=>"Abgelehnt","deaktiviert"=>"Deaktiviert"];
?>
<!DOCTYPE html><html lang="de"><head><link rel="icon" href="favicon.svg" type="image/svg+xml"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Benutzerverwaltung</title><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body><main class="app-shell"><div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Benutzerverwaltung</h1></div><a class="button button--secondary" href="auftraege.php">Zurück</a></div><?php if($flash):?><div class="notice notice--<?=h($flash["typ"])?>" role="status"><?=h($flash["nachricht"])?></div><?php endif;?><section class="glass-panel form-card"><h2>Zugänge und E-Mail</h2><div class="settings-summary"><p><strong>Selbstregistrierung:</strong> <?= $selbstregistrierung?"Aktiv":"Deaktiviert" ?></p><p><strong>E-Mail-Versand:</strong> <?= $smtp["konfiguriert"]?"Konfiguriert":"Nicht konfiguriert – Passwort-Reset-E-Mails können derzeit nicht versendet werden." ?></p></div><form method="post" action="benutzer_aktion.php" class="inline-form"><?=csrf_feld()?><input type="hidden" name="aktion" value="registrierung"><input type="hidden" name="aktiv" value="<?=$selbstregistrierung?"0":"1"?>"><button class="button button--secondary" type="submit">Selbstregistrierung <?=$selbstregistrierung?"deaktivieren":"aktivieren"?></button></form></section><section class="glass-panel form-card"><h2>Benutzer anlegen</h2><form class="form-grid" method="post" action="benutzer_aktion.php" data-validated-form novalidate><?=csrf_feld()?><input type="hidden" name="aktion" value="anlegen"><div class="form-field"><label for="admin_name">Benutzername</label><input id="admin_name" name="benutzername" minlength="3" maxlength="100" required></div><div class="form-field"><label for="admin_email">E-Mail-Adresse</label><input id="admin_email" type="email" name="email" maxlength="254" required></div><div class="form-field"><label for="admin_pw">Passwort</label><input id="admin_pw" type="password" name="passwort" minlength="8" required></div><div class="form-field"><label for="admin_pw2">Passwort wiederholen</label><input id="admin_pw2" type="password" name="passwort_wiederholen" minlength="8" required></div><div class="form-field"><label for="admin_rolle">Rolle</label><select id="admin_rolle" name="rolle"><option value="mitarbeiter">Mitarbeiter</option><option value="administrator">Administrator</option></select></div><div class="form-field form-field--wide"><label class="password-toggle"><input type="checkbox" data-password-toggle> Passwort anzeigen</label></div><button class="button button--primary" type="submit">Benutzer anlegen</button></form></section><section class="glass-panel form-card"><h2>Vorhandene Benutzer</h2><div class="archive-table-wrap"><table class="archive-table"><thead><tr><th>Benutzer</th><th>Rolle</th><th>Status</th><th>Aktionen</th></tr></thead><tbody><?php foreach($benutzer as $b):?><tr><td><strong><?=h($b["benutzername"])?></strong><br><span class="muted"><?=h($b["email"]??"Keine E-Mail-Adresse")?></span></td><td><?=h(ucfirst($b["rolle"]))?></td><td><?=h($statusNamen[$b["kontostatus"]]??$b["kontostatus"])?></td><td><div class="user-actions"><?php if((int)$b["id"]!==aktuelle_benutzer_id()):?><?php if($b["kontostatus"]!=="aktiv"):?><form method="post" action="benutzer_aktion.php" class="inline-form"><?=csrf_feld()?><input type="hidden" name="aktion" value="status"><input type="hidden" name="benutzer_id" value="<?=h($b["id"])?>"><input type="hidden" name="status" value="aktiv"><button class="button button--secondary button--compact">Freigeben</button></form><?php endif;?><?php if($b["kontostatus"]==="wartend"):?><form method="post" action="benutzer_aktion.php" class="inline-form"><?=csrf_feld()?><input type="hidden" name="aktion" value="status"><input type="hidden" name="benutzer_id" value="<?=h($b["id"])?>"><input type="hidden" name="status" value="abgelehnt"><button class="button button--ghost-danger button--compact">Ablehnen</button></form><?php elseif($b["kontostatus"]==="aktiv"):?><form method="post" action="benutzer_aktion.php" class="inline-form"><?=csrf_feld()?><input type="hidden" name="aktion" value="status"><input type="hidden" name="benutzer_id" value="<?=h($b["id"])?>"><input type="hidden" name="status" value="deaktiviert"><button class="button button--ghost-danger button--compact">Deaktivieren</button></form><?php endif;?><?php endif;?><form method="post" action="benutzer_aktion.php" class="inline-form user-password-form" data-validated-form novalidate><?=csrf_feld()?><input type="hidden" name="aktion" value="passwort"><input type="hidden" name="benutzer_id" value="<?=h($b["id"])?>"><input type="password" name="passwort" minlength="8" placeholder="Neues Passwort" aria-label="Neues Passwort für <?=h($b["benutzername"])?>" required><input type="password" name="passwort_wiederholen" minlength="8" placeholder="Wiederholen" aria-label="Passwort wiederholen für <?=h($b["benutzername"])?>" required><button class="button button--secondary button--compact">Passwort setzen</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
